/* @lc app=leetcode id=2426 lang=kotlin */
class Solution {
    fun numberOfPairs(nums1: IntArray, nums2: IntArray, diff: Int): Long = IntArray(nums1.size) { nums1[it] - nums2[it] }.let { d -> (d.map { it } + d.map { it + diff }).distinct().sorted().toIntArray().let { u -> LongArray(1).let { ans -> IntArray(u.size + 1).let { bit -> d.forEach { x -> generateSequence(u.binarySearch(x + diff) + 1) { it - (it and -it) }.takeWhile { it > 0 }.forEach { ans[0] += bit[it].toLong() }.also { generateSequence(u.binarySearch(x) + 1) { it + (it and -it) }.takeWhile { it < bit.size }.forEach { bit[it]++ } } }.run { ans[0] } } } } }
}